import{_ as e}from"./index-BHXvikYh.js";import{e as t,c as s,h as o,a as i,g as a,w as n,j as r,i as l}from"./vendor-B2TlCU4K.js";const c={class:"min-h-screen pt-32 pb-20 px-6 max-w-4xl mx-auto text-white"},d={class:"mt-12 text-center"},h=e({},[["render",function(e,h){const u=l("router-link");return t(),s("div",c,[h[1]||(h[1]=o('<h1 class="text-4xl font-bold mb-8">Cookie Policy</h1><div class="space-y-8 text-neutral-300 leading-relaxed"><section><h2 class="text-2xl font-bold text-white mb-4">1. What Are Cookies</h2><p>Cookies are small text files stored on your device when you visit websites. They help websites function properly, remember your preferences, and provide usage analytics.</p></section><section><h2 class="text-2xl font-bold text-white mb-4">2. Our Legal Basis</h2><p>We use cookies in accordance with the Privacy and Electronic Communications Regulations 2003 (PECR) and UK GDPR. Some cookies are strictly necessary for the website to function; others require your consent.</p></section><section><h2 class="text-2xl font-bold text-white mb-4">3. Cookies We Use</h2><div class="overflow-x-auto"><table class="w-full text-sm border border-neutral-700 rounded-lg overflow-hidden"><thead class="bg-neutral-800"><tr><th class="text-left p-3 font-semibold">Cookie Type</th><th class="text-left p-3 font-semibold">Purpose</th><th class="text-left p-3 font-semibold">Duration</th></tr></thead><tbody class="divide-y divide-neutral-700"><tr class="bg-neutral-900/50"><td class="p-3 font-medium text-white">Strictly Necessary</td><td class="p-3">Essential for website functionality. Cannot be disabled.</td><td class="p-3">Session</td></tr><tr class="bg-neutral-900/50"><td class="p-3 font-medium text-white">Preference Cookies</td><td class="p-3">Remember your choices (e.g., cookie consent, theme).</td><td class="p-3">1 year</td></tr><tr class="bg-neutral-900/50"><td class="p-3 font-medium text-white">Analytics</td><td class="p-3">Help us understand how visitors use our site to improve it.</td><td class="p-3">Up to 2 years</td></tr><tr class="bg-neutral-900/50"><td class="p-3 font-medium text-white">Third-Party (Cal.com)</td><td class="p-3">If you open our external booking page, the booking provider may set cookies on their domain.</td><td class="p-3">Varies</td></tr></tbody></table></div></section><section><h2 class="text-2xl font-bold text-white mb-4">4. Third-Party Cookies</h2><p>When you navigate to third-party services (such as our external Cal.com booking page), those services may set their own cookies under their own policies. We do not control those cookies and recommend reviewing the relevant provider policies.</p></section><section><h2 class="text-2xl font-bold text-white mb-4">5. Managing Cookies</h2><p>You can control and delete cookies through your browser settings. However, disabling cookies may affect website functionality.</p><ul class="list-disc list-inside space-y-2 mt-4"><li><strong>Chrome:</strong> Settings → Privacy and Security → Cookies</li><li><strong>Firefox:</strong> Settings → Privacy &amp; Security → Cookies</li><li><strong>Safari:</strong> Preferences → Privacy → Cookies</li><li><strong>Edge:</strong> Settings → Privacy → Cookies</li></ul></section><section><h2 class="text-2xl font-bold text-white mb-4">6. Your Consent Choices</h2><p>We obtain consent for non-essential cookies through our cookie banner when you first visit the site. You can:</p><ul class="list-disc list-inside space-y-2 mt-4"><li><strong class="text-white">Accept all:</strong> Enable all cookies including analytics</li><li><strong class="text-white">Essential only:</strong> Accept only strictly necessary cookies</li><li><strong class="text-white">Manage preferences:</strong> Choose which categories to enable</li></ul><p class="mt-4">You can withdraw consent at any time by clearing your cookies and revisiting the site, or by adjusting your browser settings.</p><div class="mt-4 p-4 bg-blue-500/10 border border-blue-500/30 rounded-xl"><p class="text-blue-400 text-sm"><strong>Note:</strong> Under the Data (Use and Access) Act 2025, analytics cookies for website performance monitoring may be used without consent where they do not collect personal data for marketing purposes.</p></div></section><section><h2 class="text-2xl font-bold text-white mb-4">7. Changes to This Policy</h2><p>We reserve the right to update this Cookie Policy at any time. Continued use of the website following any changes constitutes acceptance of the updated policy.</p></section><section><h2 class="text-2xl font-bold text-white mb-4">8. Contact</h2><p>For questions about our use of cookies, contact us at <a href="mailto:jake@jakefieldhouse.co.uk" class="text-blue-400 hover:underline">jake@jakefieldhouse.co.uk</a>.</p></section><p class="text-neutral-500 text-sm pt-8">Last updated: February 2026</p></div>',2)),i("div",d,[a(u,{to:"/",class:"text-neutral-500 hover:text-white transition-colors"},{default:n(()=>[...h[0]||(h[0]=[r("← Back to Home",-1)])]),_:1})])])}]]);export{h as default};
